class Solution:
    def isValid(self, word: str) -> bool:
        # Condition 1: Minimum length of 3 characters
        if len(word) < 3:
            return False

        vowels = set('aeiouAEIOU')
        has_vowel = False
        has_consonant = False

        for char in word:
            # Condition 2: Only digits and English letters allowed
            if char.isdigit():
                continue
            if char.isalpha():
                if char in vowels:
                    has_vowel = True
                else:
                    has_consonant = True
            else:
                # If character is not a digit or letter (e.g., '@', '#', '$')
                return False

        # Condition 3: At least one vowel
        # Condition 4: At least one consonant
        return has_vowel and has_consonant
