from typing import List

class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # The grid size is fixed at 3x3.
        # We need to check if there exists any 2x2 square that can be made monochromatic
        # by changing the color of at most one cell.
        # A 2x2 square is defined by its top-left corner (i, j).
        # In a 3x3 grid, the possible top-left corners are (0,0), (0,1), (1,0), and (1,1).

        for i in range(2):
            for j in range(2):
                count_b = 0
                count_w = 0

                # Iterate through the cells of the current 2x2 square
                for r in range(i, i + 2):
                    for c in range(j, j + 2):
                        if grid[r][c] == 'B':
                            count_b += 1
                        else:
                            count_w += 1

                # If a 2x2 square has 3 or more cells of the same color,
                # we can change at most 1 cell (the one with the different color)
                # to make the entire square monochromatic.
                # If it has 4 cells of the same color, 0 changes are needed.
                # If it has 2 of each, we would need 2 changes, which is not allowed.
                if count_b >= 3 or count_w >= 3:
                    return True

        return False
