class Solution:
    def numberOfAlternatingGroups(self, colors: List[int]) -> int:
        n = len(colors)
        count = 0
        for i in range(n):
            # Check the triplet starting at i: (i, i+1, i+2)
            # Using modulo to handle the circular nature of the array
            if colors[i] != colors[(i + 1) % n] and colors[(i + 1) % n] != colors[(i + 2) % n]:
                count += 1
        return count
