class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        n = len(s)
        result = []
        for i in range(n):
            # Calculate the index of the k-th character after the current character s[i].
            # Since the string is cyclic, we use modulo arithmetic: (i + k) % n.
            target_index = (i + k) % n
            result.append(s[target_index])
        return "".join(result)
