class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # If k has any bit set that is not set in n, it's impossible to transform n to k
        # because we can only flip 1s to 0s, not 0s to 1s.
        # This condition checks if k is a submask of n.
        if (n & k) != k:
            return -1

        # The number of changes needed is the number of bits that are 1 in n
        # but 0 in k. This is equivalent to the number of set bits in (n XOR k).
        return bin(n ^ k).count('1')
