class Solution:
    def canAliceWin(self, nums: List[int]) -> bool:
        single_digit = []
        double_digit = []

        for num in nums:
            if 1 <= num <= 9:
                single_digit.append(num)
            elif 10 <= num <= 99:
                double_digit.append(num)

        total_sum = sum(nums)

        # Check single-digit choice
        alice_single = sum(single_digit)
        bob_single = total_sum - alice_single
        if alice_single > bob_single:
            return True

        # Check double-digit choice
        alice_double = sum(double_digit)
        bob_double = total_sum - alice_double
        if alice_double > bob_double:
            return True

        return False
