class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Initialize the snake's position at (0, 0)
        # Corresponds to grid[0][0] = 0
        row, col = 0, 0

        for command in commands:
            if command == "UP":
                row -= 1
            elif command == "DOWN":
                row += 1
            elif command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1

        # Calculate the final linear position index
        # Formula: grid[i][j] = (i * n) + j
        return row * n + col
