from typing import List

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        results = []

        # Iterate through all subarrays of size k
        for i in range(n - k + 1):
            is_consecutive = True
            # Check if the subarray nums[i : i+k] is consecutive and sorted
            # This means nums[j] == nums[j-1] + 1 for all j from i+1 to i+k-1
            for j in range(1, k):
                if nums[i + j] != nums[i + j - 1] + 1:
                    is_consecutive = False
                    break

            if is_consecutive:
                # If the subarray is consecutive and sorted, the power is the maximum element.
                # Since it is sorted in ascending order, the last element is the maximum.
                results.append(nums[i + k - 1])
            else:
                results.append(-1)

        return results
